import sys
from collections import deque

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    k = int(data[1])
    hist = {}
    out = []
    for i in range(n):
        m = data[2 + 2 * i]
        t = int(data[3 + 2 * i])
        q = hist.get(m)
        if q is None:
            q = hist[m] = deque()
        while q and q[0] <= t - 300:
            q.popleft()
        if len(q) < k:
            q.append(t)
            out.append('true')
        else:
            out.append('false')
    print('\n'.join(out))

